insert into public.proyectos_ideas (id, area, areas2, titulo, resumen, tipo, tiempo, horas, etiquetas, intencion, datos, prog, busca, ficha, orden) values
('que-caracteristicas-tiene-una-retroalimentacion-util-y-como-mejo','educacion',array[]::text[],'¿Qué características tiene una retroalimentación útil y cómo mejora el aprendizaje?','Reúne comentarios reales que has recibido sobre tus trabajos y analiza qué características los hacen útiles o inútiles, para elaborar una guía de cómo dar y pedir buena retroalimentación.','Análisis','3 semanas',22,array['Retroalimentación','Mejora']::text[],array['investigar','crear']::text[],'propios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion analisis cualitativo. sintesis. redaccion clara. pensamiento critico. hoja de calculo. un editor de documentos. comentarios anonimizados.',$a27sld${"id": "que-caracteristicas-tiene-una-retroalimentacion-util-y-como-mejo", "area": "educacion", "areas2": [], "titulo": "¿Qué características tiene una retroalimentación útil y cómo mejora el aprendizaje?", "resumen": "Reúne comentarios reales que has recibido sobre tus trabajos y analiza qué características los hacen útiles o inútiles, para elaborar una guía de cómo dar y pedir buena retroalimentación.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Retroalimentación", "Mejora"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Un comentario como «mejorar redacción» no ayuda a nadie, mientras que uno específico sobre qué cambiar y por qué sí. Aun así, la mayoría de comentarios son breves, generales o llegan demasiado tarde.", "Entender qué hace útil a una retroalimentación permite pedirla mejor y darla mejor."], "desarrollar": ["Reúne diez a quince comentarios que hayas recibido en trabajos, sin nombres ni datos de personas. Clasifícalos según criterios como si es específico, si dice qué hacer, si llegó a tiempo y si se entiende.", "Marca cuáles te sirvieron para mejorar y cuáles no, identifica los rasgos que se repiten en los útiles y redacta una guía de cinco criterios, con ejemplos de comentarios reescritos."], "ampliaciones": [{"titulo": "Comentarios reescritos", "aporta": "toma comentarios vagos y reescríbelos para que sean útiles."}, {"titulo": "Pedir buena retroalimentación", "aporta": "diseña preguntas para pedir comentarios a docentes o compañeros."}, {"titulo": "Retroalimentación entre pares", "aporta": "prueba la guía en una actividad con compañeros."}], "objetivos": ["Clasificar comentarios recibidos.", "Identificar rasgos de los útiles.", "Elaborar una guía.", "Probarla."], "habilidades": ["Análisis cualitativo.", "Síntesis.", "Redacción clara.", "Pensamiento crítico."], "herramientas": ["Hoja de cálculo.", "Un editor de documentos.", "Comentarios anonimizados."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Quita nombres de docentes y compañeros de cualquier comentario que uses y no critiques a personas concretas."], "otroSector": "La misma guía sirve para dar retroalimentación en el trabajo, en revisiones de código o de informes."}$a27sld$::jsonb,34),
('como-cambia-el-aprendizaje-cuando-conocemos-nuestros-errores-dur','educacion',array[]::text[],'¿Cómo cambia el aprendizaje cuando conocemos nuestros errores durante el proceso y no solo al final?','Compara practicar con corrección inmediata frente a corregir al final, y observa cómo cambian tus errores repetidos, tu comprensión y tu motivación.','Investigación','3 a 4 semanas',22,array['Errores','Retroalimentación inmediata']::text[],array['investigar','resolver']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social diseno de experimentos. analisis de errores. autoevaluacion. redaccion de conclusiones. ejercicios con soluciones. hoja de calculo. un cronometro.',$a28sld${"id": "como-cambia-el-aprendizaje-cuando-conocemos-nuestros-errores-dur", "area": "educacion", "areas2": [], "titulo": "¿Cómo cambia el aprendizaje cuando conocemos nuestros errores durante el proceso y no solo al final?", "resumen": "Compara practicar con corrección inmediata frente a corregir al final, y observa cómo cambian tus errores repetidos, tu comprensión y tu motivación.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 22, "etiquetas": ["Errores", "Retroalimentación inmediata"], "intencion": ["investigar", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["En muchos cursos las notas de una práctica llegan semanas después, cuando ya pasó el tema. Si el error se descubre tarde, se repite varias veces antes de corregirlo.", "Probar el efecto de conocer los errores a tiempo muestra cuánto vale revisar mientras se aprende."], "desarrollar": ["Elige dos conjuntos de ejercicios de dificultad parecida. En uno, corrige cada ejercicio con la solución apenas lo termines; en el otro, resuelve todos y corrige al final. Registra cuántos errores repites en cada caso.", "Una semana después, resuelve ejercicios nuevos de ambos tipos y compara el desempeño. Resume cuándo conviene revisar de inmediato y cuándo dejar la corrección al final."], "ampliaciones": [{"titulo": "Tipo de error", "aporta": "clasifica errores por conceptuales, de cálculo y de descuido."}, {"titulo": "Cuaderno de errores", "aporta": "mantén un registro de errores frecuentes y mide su efecto."}, {"titulo": "Con un compañero", "aporta": "intercambien soluciones para corregirse mutuamente."}], "objetivos": ["Comparar corrección inmediata y final.", "Contar errores repetidos.", "Medir el efecto en el aprendizaje.", "Proponer una regla."], "habilidades": ["Diseño de experimentos.", "Análisis de errores.", "Autoevaluación.", "Redacción de conclusiones."], "herramientas": ["Ejercicios con soluciones.", "Hoja de cálculo.", "Un cronómetro."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Usa ejercicios con solución confiable para que la corrección sea correcta."], "otroSector": "El mismo experimento sirve para comparar formas de entrenar a nuevos trabajadores o de revisar códigos."}$a28sld$::jsonb,35),
('disenando-una-rubrica-sencilla-para-evaluar-una-exposicion-un-in','educacion',array['sociedad']::text[],'Diseñando una rúbrica sencilla para evaluar una exposición, un informe o un proyecto','Diseña una rúbrica clara, con pocos criterios y niveles bien descritos, para evaluar un trabajo académico, y pruébala con trabajos de ejemplo para ver si dos personas coinciden al calificar.','Prototipo','3 semanas',22,array['Rúbricas','Evaluación']::text[],array['crear']::text[],'ficticios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion diseno de instrumentos. redaccion precisa. comparacion de criterios. mejora iterativa. una hoja de calculo o documento. trabajos de ejemplo. dos personas evaluadoras.',$a29sld${"id": "disenando-una-rubrica-sencilla-para-evaluar-una-exposicion-un-in", "area": "educacion", "areas2": ["sociedad"], "titulo": "Diseñando una rúbrica sencilla para evaluar una exposición, un informe o un proyecto", "resumen": "Diseña una rúbrica clara, con pocos criterios y niveles bien descritos, para evaluar un trabajo académico, y pruébala con trabajos de ejemplo para ver si dos personas coinciden al calificar.", "tipo": "Prototipo", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Rúbricas", "Evaluación"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Una rúbrica ayuda a que el estudiante sepa qué se espera y al docente a calificar con criterios parejos. Pero muchas rúbricas son confusas, tienen demasiados criterios o niveles que no se distinguen.", "Probarla con trabajos de ejemplo muestra si realmente se entiende y se aplica igual por distintas personas."], "desarrollar": ["Elige un tipo de trabajo, como una exposición, un informe o un proyecto, y define cuatro a cinco criterios con descripciones claras de tres niveles. Redacta tres trabajos ficticios de distinta calidad como ejemplo.", "Pide a dos personas que califiquen los ejemplos con tu rúbrica por separado, compara si coinciden y ajusta las descripciones donde hubo discrepancias. Publica la versión final con ejemplos."], "ampliaciones": [{"titulo": "Autoevaluación", "aporta": "adapta la rúbrica para que el estudiante se evalúe antes de entregar."}, {"titulo": "Ponderación", "aporta": "prueba pesos distintos para los criterios."}, {"titulo": "Versión para niños", "aporta": "simplifica la rúbrica para escolares."}], "objetivos": ["Definir criterios claros.", "Describir niveles de desempeño.", "Probar la coincidencia entre evaluadores.", "Mejorar la rúbrica."], "habilidades": ["Diseño de instrumentos.", "Redacción precisa.", "Comparación de criterios.", "Mejora iterativa."], "herramientas": ["Una hoja de cálculo o documento.", "Trabajos de ejemplo.", "Dos personas evaluadoras."], "lineamientos": ["No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Usa trabajos ficticios de ejemplo y no trabajos reales de compañeros sin su permiso.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión."], "otroSector": "La misma rúbrica sirve para evaluar presentaciones de ventas, portafolios o entrevistas."}$a29sld$::jsonb,36),
('analizando-como-recibimos-y-usamos-comentarios-sobre-nuestro-des','educacion',array[]::text[],'Analizando cómo recibimos y usamos comentarios sobre nuestro desempeño: ¿qué tan clara es la retroalimentación?','Analiza si la retroalimentación que recibes en tus actividades es clara, a tiempo y utilizable, y qué haces tú con ella: la lees, la aplicas o la ignoras.','Análisis','3 semanas',20,array['Retroalimentación','Claridad']::text[],array['investigar']::text[],'propios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion analisis cualitativo. autoevaluacion. comunicacion. mejora continua. comentarios recibidos. hoja de calculo. un editor de documentos.',$a30sld${"id": "analizando-como-recibimos-y-usamos-comentarios-sobre-nuestro-des", "area": "educacion", "areas2": [], "titulo": "Analizando cómo recibimos y usamos comentarios sobre nuestro desempeño: ¿qué tan clara es la retroalimentación?", "resumen": "Analiza si la retroalimentación que recibes en tus actividades es clara, a tiempo y utilizable, y qué haces tú con ella: la lees, la aplicas o la ignoras.", "tipo": "Análisis", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Retroalimentación", "Claridad"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["A veces el problema no es la falta de comentarios, sino que no se entienden, llegan tarde o no sabemos qué hacer con ellos. También ocurre que los recibimos, pero no los aplicamos en el siguiente trabajo.", "Mirar los dos lados, qué recibo y qué hago con eso, da pistas para mejorar el ciclo completo."], "desarrollar": ["Reúne los comentarios de tres a cinco actividades recientes y evalúa para cada uno si fue claro, específico, a tiempo y si dijo qué hacer. Registra qué hiciste con él: lo aplicaste, lo preguntaste o lo ignoraste.", "Identifica patrones, como no entender ciertos tipos de comentarios o no aplicarlos por falta de tiempo, y propón acciones: preguntar al docente, hacer una lista de cambios y revisarla en el siguiente trabajo."], "ampliaciones": [{"titulo": "Encuesta anónima", "aporta": "con permiso de un docente, aplica una encuesta breve a compañeros."}, {"titulo": "Pedir aclaraciones", "aporta": "prepara preguntas modelo para aclarar comentarios."}, {"titulo": "Plan de mejora", "aporta": "diseña un formato para convertir un comentario en una acción."}], "objetivos": ["Evaluar la claridad de comentarios.", "Registrar su uso.", "Identificar patrones.", "Proponer acciones."], "habilidades": ["Análisis cualitativo.", "Autoevaluación.", "Comunicación.", "Mejora continua."], "herramientas": ["Comentarios recibidos.", "Hoja de cálculo.", "Un editor de documentos."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Presenta tu análisis sin nombrar docentes: es un estudio de claridad, no una queja."], "otroSector": "El mismo análisis sirve para revisar evaluaciones de desempeño en un empleo."}$a30sld$::jsonb,37),
('evaluando-distintas-formas-de-autoevaluacion-para-aprender-mejor','educacion',array[]::text[],'Evaluando distintas formas de autoevaluación para aprender mejor','Prueba formas de autoevaluación, como listas de verificación, pruebas propias o comparar con soluciones, y mide qué tan bien reflejan lo que de verdad sabes.','Investigación','3 semanas',20,array['Autoevaluación','Metacognición']::text[],array['investigar','crear']::text[],'propios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion metacognicion. diseno de pruebas. analisis de datos. autocritica. hoja de calculo. pruebas propias. soluciones confiables.',$a31sld${"id": "evaluando-distintas-formas-de-autoevaluacion-para-aprender-mejor", "area": "educacion", "areas2": [], "titulo": "Evaluando distintas formas de autoevaluación para aprender mejor", "resumen": "Prueba formas de autoevaluación, como listas de verificación, pruebas propias o comparar con soluciones, y mide qué tan bien reflejan lo que de verdad sabes.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Autoevaluación", "Metacognición"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Muchos estudiantes creen que dominan un tema porque lo reconocen al leerlo, pero fallan cuando deben resolver problemas. La autoevaluación puede corregir esa falsa seguridad si está bien hecha.", "Compararla con una prueba real muestra qué tan confiables son tus propias estimaciones."], "desarrollar": ["Elige tres temas y evalúa tu dominio con tres métodos distintos: marcar una lista de lo que crees saber, resolver una prueba propia sin ayudas y comparar tus respuestas con soluciones. Anota qué nota te darías antes de cada prueba.", "Compara tu estimación con tu resultado real, calcula en qué temas te sobreestimas o subestimas y elige la forma de autoevaluarte que más se acerque a la realidad."], "ampliaciones": [{"titulo": "Seguridad vs resultado", "aporta": "mide cuán seguro estabas de cada respuesta frente a si era correcta."}, {"titulo": "Autoevaluación guiada", "aporta": "diseña una lista de verificación para un curso."}, {"titulo": "Frecuencia", "aporta": "compara autoevaluarte semanalmente o solo antes del examen."}], "objetivos": ["Comparar métodos de autoevaluación.", "Medir la precisión de tu estimación.", "Elegir el método más fiable.", "Documentar los resultados."], "habilidades": ["Metacognición.", "Diseño de pruebas.", "Análisis de datos.", "Autocrítica."], "herramientas": ["Hoja de cálculo.", "Pruebas propias.", "Soluciones confiables."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Si te sobreestimas, es un dato útil, no un fracaso."], "otroSector": "La misma práctica sirve para autoevaluar competencias en un puesto de trabajo."}$a31sld$::jsonb,38),
('una-propuesta-de-tutorias-entre-estudiantes-para-aprender-materi','educacion',array['sociedad']::text[],'Una propuesta de tutorías entre estudiantes para aprender materias difíciles','Diseña un programa de tutorías entre estudiantes de distintos ciclos para cursos difíciles, con cómo elegir tutores, organizar las sesiones, medir resultados y cuidar la calidad.','Plan','4 a 6 semanas',26,array['Tutorías entre pares','Aprendizaje colaborativo']::text[],array['crear','resolver']::text[],'ficticios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion diseno de programas. comunicacion. planificacion. evaluacion de resultados. un editor de documentos. hoja de calculo. formularios de inscripcion.',$a32sld${"id": "una-propuesta-de-tutorias-entre-estudiantes-para-aprender-materi", "area": "educacion", "areas2": ["sociedad"], "titulo": "Una propuesta de tutorías entre estudiantes para aprender materias difíciles", "resumen": "Diseña un programa de tutorías entre estudiantes de distintos ciclos para cursos difíciles, con cómo elegir tutores, organizar las sesiones, medir resultados y cuidar la calidad.", "tipo": "Plan", "tiempo": "4 a 6 semanas", "horas": 26, "etiquetas": ["Tutorías entre pares", "Aprendizaje colaborativo"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Los estudiantes de ciclos superiores suelen ayudar a los más jóvenes de manera informal, pero sin organización ni criterios. Muchas veces los de ciclos iniciales no saben a quién acudir y los tutores no saben cómo enseñar.", "Un programa sencillo y bien pensado ordena esa ayuda y mejora su calidad."], "desarrollar": ["Define el objetivo del programa, los cursos que atiende, el perfil del tutor, cómo se inscribe un estudiante y cómo se programan las sesiones. Escribe una guía breve para tutores con buenas prácticas y límites.", "Prueba el programa en pequeño, con tres a cinco parejas, mide asistencia y satisfacción y ajusta. Resume la propuesta en un documento listo para presentar a una asociación estudiantil o un docente."], "ampliaciones": [{"titulo": "Formación de tutores", "aporta": "diseña una sesión breve para preparar tutores."}, {"titulo": "Indicadores", "aporta": "propón cómo medir el efecto de las tutorías."}, {"titulo": "Reconocimiento", "aporta": "diseña formas de reconocer el trabajo de los tutores."}], "objetivos": ["Diseñar un programa de tutorías.", "Definir roles y reglas.", "Probarlo en pequeño.", "Presentar la propuesta."], "habilidades": ["Diseño de programas.", "Comunicación.", "Planificación.", "Evaluación de resultados."], "herramientas": ["Un editor de documentos.", "Hoja de cálculo.", "Formularios de inscripción."], "lineamientos": ["Pide autorización y apoyo a la institución o asociación antes de poner en marcha un programa real.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión."], "otroSector": "La misma propuesta sirve para mentorías en empresas o entre profesionales."}$a32sld$::jsonb,39),
('como-organizar-una-sesion-de-tutoria-para-que-el-estudiante-apre','educacion',array[]::text[],'¿Cómo organizar una sesión de tutoría para que el estudiante aprenda a resolver problemas por sí mismo?','Diseña una estructura de sesión de tutoría que haga preguntas y dé pistas en lugar de resolver los ejercicios, para que quien recibe ayuda aprenda a avanzar solo y ganar autonomía.','Guía','3 semanas',20,array['Tutoría','Autonomía']::text[],array['crear','resolver']::text[],'ficticios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion formulacion de preguntas. pedagogia basica. comunicacion. diseno de guias. un editor de documentos. ejercicios resueltos. un companero para el juego de roles.',$a33sld${"id": "como-organizar-una-sesion-de-tutoria-para-que-el-estudiante-apre", "area": "educacion", "areas2": [], "titulo": "¿Cómo organizar una sesión de tutoría para que el estudiante aprenda a resolver problemas por sí mismo?", "resumen": "Diseña una estructura de sesión de tutoría que haga preguntas y dé pistas en lugar de resolver los ejercicios, para que quien recibe ayuda aprenda a avanzar solo y ganar autonomía.", "tipo": "Guía", "tiempo": "3 semanas", "horas": 20, "etiquetas": ["Tutoría", "Autonomía"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Un tutor bienintencionado muchas veces termina resolviendo el ejercicio, y el estudiante sale con la solución pero sin haber aprendido a llegar a ella. Eso genera dependencia.", "Una sesión bien estructurada, con preguntas guía y práctica, ayuda a que el estudiante gane autonomía."], "desarrollar": ["Diseña una estructura de sesión con pasos: revisar qué intentó el estudiante, hacer preguntas en vez de dar respuestas, ofrecer pistas graduales, dejar un ejercicio de práctica y cerrar con un resumen del aprendizaje.", "Escribe un guion con ejemplos de preguntas guía para dos tipos de problemas, practícalo en un juego de roles con un compañero y ajusta. Elabora una guía breve para tutores."], "ampliaciones": [{"titulo": "Niveles de pistas", "aporta": "define una escala de pistas de menos a más ayuda."}, {"titulo": "Cuándo explicar", "aporta": "define cuándo sí conviene dar una explicación completa."}, {"titulo": "Cierre de sesión", "aporta": "diseña preguntas de cierre para ver qué se entendió."}], "objetivos": ["Diseñar una estructura de sesión.", "Elaborar preguntas guía.", "Practicar con un guion.", "Redactar una guía."], "habilidades": ["Formulación de preguntas.", "Pedagogía básica.", "Comunicación.", "Diseño de guías."], "herramientas": ["Un editor de documentos.", "Ejercicios resueltos.", "Un compañero para el juego de roles."], "lineamientos": ["No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Practica con ejercicios ficticios o de práctica y no con trabajos evaluados."], "otroSector": "La misma estructura sirve para capacitar nuevos empleados o para mentorías de programación."}$a33sld$::jsonb,40),
('el-impacto-de-las-tutorias-entre-pares-en-la-comprension-de-un-t','educacion',array[]::text[],'El impacto de las tutorías entre pares en la comprensión de un tema','Mide qué cambia en la comprensión de un tema cuando una persona recibe tutoría de un compañero frente a estudiar sola, y qué aprende también quien enseña.','Investigación','3 a 4 semanas',22,array['Tutorías entre pares','Comprensión']::text[],array['investigar']::text[],'propios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion diseno de experimentos. analisis simple de datos. comunicacion. redaccion. pruebas cortas propias. hoja de calculo. dos o tres parejas voluntarias.',$a34sld${"id": "el-impacto-de-las-tutorias-entre-pares-en-la-comprension-de-un-t", "area": "educacion", "areas2": [], "titulo": "El impacto de las tutorías entre pares en la comprensión de un tema", "resumen": "Mide qué cambia en la comprensión de un tema cuando una persona recibe tutoría de un compañero frente a estudiar sola, y qué aprende también quien enseña.", "tipo": "Investigación", "tiempo": "3 a 4 semanas", "horas": 22, "etiquetas": ["Tutorías entre pares", "Comprensión"], "intencion": ["investigar"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Las tutorías entre compañeros se hacen mucho, pero casi no se sabe si funcionan. Pueden ayudar a quien aprende y también a quien enseña, o convertirse en una conversación sin avance.", "Medirlo, aunque sea en pequeño, ayuda a decidir si conviene organizarlas mejor."], "desarrollar": ["Con dos o tres parejas voluntarias, elige un tema y mide con una prueba corta la comprensión antes y después de una sesión de tutoría. Haz lo mismo con un tema parecido estudiado en solitario.", "Compara las mejoras de quien aprende, observa qué cambió en quien enseña y escribe qué condiciones hicieron más útil la sesión, como tiempo, preparación y preguntas guía."], "ampliaciones": [{"titulo": "Duración", "aporta": "compara sesiones de 30 y de 60 minutos."}, {"titulo": "Una sesión o varias", "aporta": "compara una sola sesión larga con varias cortas."}, {"titulo": "Encuesta de percepción", "aporta": "agrega una encuesta breve y voluntaria a las parejas."}], "objetivos": ["Medir comprensión antes y después.", "Comparar con estudio solitario.", "Analizar el efecto en el tutor.", "Redactar conclusiones."], "habilidades": ["Diseño de experimentos.", "Análisis simple de datos.", "Comunicación.", "Redacción."], "herramientas": ["Pruebas cortas propias.", "Hoja de cálculo.", "Dos o tres parejas voluntarias."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Los resultados con pocas parejas son ilustrativos y no generalizables."], "otroSector": "El mismo estudio sirve para evaluar mentorías en el trabajo o programas de capacitación."}$a34sld$::jsonb,41),
('disenando-un-taller-breve-para-ensenar-una-habilidad-academica-a','educacion',array[]::text[],'Diseñando un taller breve para enseñar una habilidad académica a otros estudiantes','Diseña un taller de una hora para enseñar una habilidad académica, como tomar apuntes, estudiar con tarjetas o buscar fuentes, con objetivos, actividades, materiales y una forma de saber si se aprendió.','Plan','3 a 4 semanas',22,array['Talleres','Habilidades académicas']::text[],array['crear']::text[],'ficticios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion diseno de actividades. comunicacion oral. planificacion. evaluacion. un editor de presentaciones o pizarra. hojas de practica. un formulario de opinion.',$a35sld${"id": "disenando-un-taller-breve-para-ensenar-una-habilidad-academica-a", "area": "educacion", "areas2": [], "titulo": "Diseñando un taller breve para enseñar una habilidad académica a otros estudiantes", "resumen": "Diseña un taller de una hora para enseñar una habilidad académica, como tomar apuntes, estudiar con tarjetas o buscar fuentes, con objetivos, actividades, materiales y una forma de saber si se aprendió.", "tipo": "Plan", "tiempo": "3 a 4 semanas", "horas": 22, "etiquetas": ["Talleres", "Habilidades académicas"], "intencion": ["crear"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Muchos estudiantes saben cosas útiles pero no las enseñan, y muchas habilidades académicas no se aprenden en ningún curso. Un taller corto puede cubrir ese vacío, pero requiere diseño para no ser una charla larga y aburrida.", "Un buen diseño convierte lo que sabes en algo que otros pueden aprender y aplicar."], "desarrollar": ["Elige una habilidad que domines y define un objetivo medible para el final del taller. Diseña una secuencia de una hora con una demostración corta, práctica guiada, práctica autónoma y cierre, y prepara los materiales.", "Pruébalo con tres a cinco compañeros, mide con una actividad o preguntas finales si lograron el objetivo, recoge opiniones y ajusta. Deja una versión final lista para reutilizar."], "ampliaciones": [{"titulo": "Material para llevar", "aporta": "prepara una hoja resumen para que los participantes repasen."}, {"titulo": "Versión virtual", "aporta": "adapta el taller para una sesión en línea."}, {"titulo": "Evaluación del taller", "aporta": "diseña una encuesta breve de satisfacción y aprendizaje."}], "objetivos": ["Definir un objetivo medible.", "Diseñar la secuencia de actividades.", "Probar el taller.", "Mejorarlo."], "habilidades": ["Diseño de actividades.", "Comunicación oral.", "Planificación.", "Evaluación."], "herramientas": ["Un editor de presentaciones o pizarra.", "Hojas de práctica.", "Un formulario de opinión."], "lineamientos": ["No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Usa solo material propio o con permiso."], "otroSector": "El mismo diseño sirve para capacitaciones internas breves en una empresa."}$a35sld$::jsonb,42),
('una-guia-para-aprender-un-tema-dificil-con-ejemplos-y-ejercicios','educacion',array[]::text[],'Una guía para aprender un tema difícil con ejemplos y ejercicios de dificultad progresiva','Elige un tema difícil que domines y diseña una guía con ejemplos resueltos y una colección de ejercicios que van de lo simple a lo complejo, para que otra persona lo aprenda paso a paso.','Guía','4 semanas',26,array['Ejercicios progresivos','Aprendizaje gradual']::text[],array['crear','resolver']::text[],'ficticios',NULL,'educacion ingenieria de sistemas ciencia de datos psicologia comunicaciones estadistica diseno administracion diseno didactico. redaccion clara. resolucion de problemas. pruebas con usuarios. un editor de documentos. un editor de ecuaciones si hace falta. un companero voluntario.',$a36sld${"id": "una-guia-para-aprender-un-tema-dificil-con-ejemplos-y-ejercicios", "area": "educacion", "areas2": [], "titulo": "Una guía para aprender un tema difícil con ejemplos y ejercicios de dificultad progresiva", "resumen": "Elige un tema difícil que domines y diseña una guía con ejemplos resueltos y una colección de ejercicios que van de lo simple a lo complejo, para que otra persona lo aprenda paso a paso.", "tipo": "Guía", "tiempo": "4 semanas", "horas": 26, "etiquetas": ["Ejercicios progresivos", "Aprendizaje gradual"], "intencion": ["crear", "resolver"], "datos": "ficticios", "datosTexto": "ficticios: trabaja con casos inventados o simulados; no hace falta pedir permiso a nadie ni usar información real de otras personas.", "carreras": ["Educación", "Ingeniería de Sistemas", "Ciencia de Datos", "Psicología", "Comunicaciones", "Estadística", "Diseño", "Administración"], "problema": ["Los temas difíciles asustan cuando se enfrentan de golpe: se pasa de la definición a problemas complejos sin escalones intermedios. Por eso muchos se rinden antes de entender los fundamentos.", "Una secuencia bien graduada, con ejemplos y práctica, hace que el tema se sienta alcanzable."], "desarrollar": ["Divide el tema en cinco o seis pasos, desde la idea más básica hasta una aplicación completa. Para cada paso escribe una explicación corta, un ejemplo resuelto en detalle y tres a cinco ejercicios de dificultad creciente con solución.", "Pruébala con un compañero que no conozca el tema, observa dónde se traba, ajusta el orden y la dificultad y añade pistas. Entrega la guía final con índice y una autoevaluación."], "ampliaciones": [{"titulo": "Errores típicos", "aporta": "agrega una sección con errores frecuentes y cómo evitarlos."}, {"titulo": "Niveles de ayuda", "aporta": "añade pistas graduales para cada ejercicio."}, {"titulo": "Versión en video", "aporta": "graba una explicación breve para cada paso."}], "objetivos": ["Dividir un tema en pasos.", "Redactar ejemplos y ejercicios graduados.", "Probar la guía con un principiante.", "Mejorarla."], "habilidades": ["Diseño didáctico.", "Redacción clara.", "Resolución de problemas.", "Pruebas con usuarios."], "herramientas": ["Un editor de documentos.", "Un editor de ecuaciones si hace falta.", "Un compañero voluntario."], "lineamientos": ["No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Cita las fuentes que uses para respaldar lo que afirmas sobre cómo se aprende, y distingue entre lo que muestra la evidencia y lo que es tu opinión.", "Resuelve tú mismo todos los ejercicios antes de publicarlos para evitar errores en las soluciones."], "otroSector": "La misma estructura sirve para capacitar en un software, en un oficio o en un deporte."}$a36sld$::jsonb,43),
('creando-una-guia-de-apoyo-para-estudiantes-que-inician-un-curso','educacion',array['tecnologia']::text[],'Creando una guía de apoyo para estudiantes que inician un curso difícil','Prepara una guía para quienes comienzan un curso que suele resultar complicado, con qué esperar, qué repasar antes, cómo estudiarlo, errores comunes y a quién acudir.','Guía','3 a 4 semanas',22,array['Cursos difíciles','Guías de apoyo']::text[],array['crear']::text[],'propios',NULL,'ingenieria de sistemas educacion psicologia ingenieria industrial administracion estadistica comunicaciones trabajo social entrevistas. sintesis. redaccion clara. empatia. un editor de documentos. el silabo del curso. una guia de entrevista.',$a37sld${"id": "creando-una-guia-de-apoyo-para-estudiantes-que-inician-un-curso", "area": "educacion", "areas2": ["tecnologia"], "titulo": "Creando una guía de apoyo para estudiantes que inician un curso difícil", "resumen": "Prepara una guía para quienes comienzan un curso que suele resultar complicado, con qué esperar, qué repasar antes, cómo estudiarlo, errores comunes y a quién acudir.", "tipo": "Guía", "tiempo": "3 a 4 semanas", "horas": 22, "etiquetas": ["Cursos difíciles", "Guías de apoyo"], "intencion": ["crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Ingeniería de Sistemas", "Educación", "Psicología", "Ingeniería Industrial", "Administración", "Estadística", "Comunicaciones", "Trabajo Social"], "problema": ["Algunos cursos tienen fama de difíciles, y esa fama asusta o hace que se subestime el esfuerzo. Muchos llegan sin saber qué conocimientos previos necesitan ni cómo conviene estudiarlo.", "Una guía hecha por alguien que ya lo cursó puede ahorrar tropiezos."], "desarrollar": ["Entrevista de manera informal a tres a cinco estudiantes que ya aprobaron el curso, con su permiso, sobre qué les costó más, qué los ayudó y qué harían distinto. Combina sus respuestas con tu propia experiencia y el sílabo.", "Redacta una guía con qué esperar semana a semana, conocimientos previos a repasar, hábitos recomendados, recursos y errores comunes. Pruébala con un estudiante que empieza el curso y ajusta."], "ampliaciones": [{"titulo": "Lista de preguntas frecuentes", "aporta": "añade las dudas más comunes y sus respuestas."}, {"titulo": "Calendario sugerido", "aporta": "propón un calendario de estudio para el ciclo."}, {"titulo": "Recursos recomendados", "aporta": "arma una lista corta con enlaces confiables."}], "objetivos": ["Recoger experiencias de estudiantes.", "Identificar conocimientos previos.", "Redactar la guía.", "Probarla con un nuevo estudiante."], "habilidades": ["Entrevistas.", "Síntesis.", "Redacción clara.", "Empatía."], "herramientas": ["Un editor de documentos.", "El sílabo del curso.", "Una guía de entrevista."], "lineamientos": ["No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Respeta la confidencialidad de lo que te cuenten y no publiques nombres sin permiso.", "No critiques a docentes concretos: describe el curso con respeto."], "otroSector": "La misma guía sirve para orientar a quien empieza en un empleo o en un lenguaje de programación."}$a37sld$::jsonb,44),
('como-preparar-una-exposicion-academica-sin-limitarse-a-memorizar','educacion',array['arte']::text[],'Cómo preparar una exposición académica sin limitarse a memorizar diapositivas','Crea una guía práctica para preparar una exposición que se entienda y mantenga la atención, con estructura clara, apoyos visuales útiles y ensayo, en vez de leer o memorizar las diapositivas.','Guía','3 semanas',22,array['Exposiciones','Comunicación oral']::text[],array['crear','resolver']::text[],'propios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion comunicacion oral. diseno de presentaciones. autoevaluacion. redaccion de guias. un editor de presentaciones. una grabadora. companeros para opinar.',$a38sld${"id": "como-preparar-una-exposicion-academica-sin-limitarse-a-memorizar", "area": "educacion", "areas2": ["arte"], "titulo": "Cómo preparar una exposición académica sin limitarse a memorizar diapositivas", "resumen": "Crea una guía práctica para preparar una exposición que se entienda y mantenga la atención, con estructura clara, apoyos visuales útiles y ensayo, en vez de leer o memorizar las diapositivas.", "tipo": "Guía", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Exposiciones", "Comunicación oral"], "intencion": ["crear", "resolver"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Muchas exposiciones se limitan a leer las diapositivas, y el público se desconecta. Memorizar un texto largo tampoco ayuda: al olvidar una línea, se pierde el hilo.", "Una buena preparación se apoya en entender el mensaje y practicar cómo explicarlo."], "desarrollar": ["Define los pasos de preparación: decidir el mensaje principal, estructurar la exposición en tres partes, preparar diapositivas con poco texto, ensayar con una guía de ideas clave y no con un guion completo. Ilustra cada paso con ejemplos.", "Prueba la guía preparando una exposición de cinco minutos sobre un tema, grábate, pide comentarios a dos compañeros y compara con una exposición hecha sin la guía. Ajusta la guía con lo aprendido."], "ampliaciones": [{"titulo": "Manejo de nervios", "aporta": "añade técnicas de preparación para reducir la ansiedad."}, {"titulo": "Preguntas del público", "aporta": "prepara cómo responder preguntas difíciles."}, {"titulo": "Exposición virtual", "aporta": "adapta la guía a presentaciones en línea."}], "objetivos": ["Definir los pasos de preparación.", "Aplicarlos a una exposición.", "Comparar antes y después.", "Redactar la guía."], "habilidades": ["Comunicación oral.", "Diseño de presentaciones.", "Autoevaluación.", "Redacción de guías."], "herramientas": ["Un editor de presentaciones.", "Una grabadora.", "Compañeros para opinar."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Si grabas, hazlo solo contigo mismo y no publiques sin permiso de quienes aparezcan."], "otroSector": "La misma guía sirve para presentaciones de trabajo, ventas o defensas de proyecto."}$a38sld$::jsonb,45),
('que-hace-que-una-explicacion-sea-facil-o-dificil-de-entender-com','educacion',array['sociedad']::text[],'¿Qué hace que una explicación sea fácil o difícil de entender? Cómo explicar un concepto complejo a alguien que recién lo aprende','Compara explicaciones de un mismo concepto, analiza qué las hace claras o confusas y construye una guía para explicar a quien recién empieza.','Investigación','3 semanas',22,array['Explicaciones','Claridad']::text[],array['investigar','crear']::text[],'propios',NULL,'educacion psicologia ingenieria de sistemas comunicaciones diseno trabajo social sociologia administracion comunicacion. analisis cualitativo. pensamiento didactico. redaccion clara. tres explicaciones del mismo concepto. hoja de calculo. tres personas voluntarias.',$a39sld${"id": "que-hace-que-una-explicacion-sea-facil-o-dificil-de-entender-com", "area": "educacion", "areas2": ["sociedad"], "titulo": "¿Qué hace que una explicación sea fácil o difícil de entender? Cómo explicar un concepto complejo a alguien que recién lo aprende", "resumen": "Compara explicaciones de un mismo concepto, analiza qué las hace claras o confusas y construye una guía para explicar a quien recién empieza.", "tipo": "Investigación", "tiempo": "3 semanas", "horas": 22, "etiquetas": ["Explicaciones", "Claridad"], "intencion": ["investigar", "crear"], "datos": "propios", "datosTexto": "mediciones propias: las que tú mismo tomes u observes en tu entorno, sin recoger datos personales de otras personas.", "carreras": ["Educación", "Psicología", "Ingeniería de Sistemas", "Comunicaciones", "Diseño", "Trabajo Social", "Sociología", "Administración"], "problema": ["Hay personas que saben mucho y explican mal, y otras que explican sencillo. Lo difícil suele ser el vocabulario, los saltos de pasos o las explicaciones que parten de lo que el otro todavía no sabe.", "Entender qué ayuda y qué estorba permite explicar mejor y también estudiar mejor."], "desarrollar": ["Elige un concepto y reúne tres explicaciones distintas, por ejemplo de un libro, de un video y de un compañero. Pide a tres personas que no lo conozcan que las lean o escuchen y expliquen con sus palabras qué entendieron.", "Analiza qué rasgos se asocian con las explicaciones que se entendieron, como ejemplos, orden y vocabulario, y redacta una guía de cinco consejos con ejemplos de cómo reescribir una explicación difícil."], "ampliaciones": [{"titulo": "Con analogías", "aporta": "prueba si las analogías mejoran la comprensión."}, {"titulo": "Distintos públicos", "aporta": "compara cómo explicar a un colega y a un principiante."}, {"titulo": "Explicación en capas", "aporta": "diseña una explicación en niveles de detalle."}], "objetivos": ["Comparar explicaciones.", "Medir la comprensión.", "Identificar rasgos de claridad.", "Redactar una guía."], "habilidades": ["Comunicación.", "Análisis cualitativo.", "Pensamiento didáctico.", "Redacción clara."], "herramientas": ["Tres explicaciones del mismo concepto.", "Hoja de cálculo.", "Tres personas voluntarias."], "lineamientos": ["Es un estudio pequeño con pocas personas o contigo mismo: no pretendas sacar conclusiones generales, solo patrones que te ayuden a decidir.", "No recojas datos personales de otras personas: usa códigos o promedios, pide permiso para cualquier prueba y respeta quién prefiere no participar.", "Cita las fuentes de las explicaciones que compares."], "otroSector": "La misma guía sirve para explicar un producto o un procedimiento a un cliente o a un nuevo empleado."}$a39sld$::jsonb,46)
